    ];
    // widths + available are returned by useFittingTabCount
    while (widthOf(inline) + MORE_MENU_RESERVE_PX > available && inline.length > 1) {
        const dropped = inline[inline.length - 1];
        inline = inline.slice(0, -1);
        overflow = [dropped, ...overflow];
    }
}
