```javascript
// Jest prints BOTH sides: for a `reasons: false` row the Expected line is
// `- "reasoned": false`, so matching any line reports the opposite cause.
// Read the RECEIVED side only.
const received = lines.find((l) => /^\s*\+\s.*"reasoned":\s*(true|false)/.test(l));
if (received) {
    return /"reasoned":\s*false/.test(received)
        ? 'returned 200 but billed NO reasoning tokens — the silent drift this tier exists to catch'
        : 'returned 200 and STARTED billing reasoning — a row pinned `reasons: false` no longer holds, the config changed upstream';
}
return collapse(lines.find((l) => l.trim()) ?? 'see log');
