```typescript
const currentLevel = this.resolveContextLevel({ directoryId, repositoryId });
const ruleLevel = this.resolveRuleLevel(rule);

// 1. Handle Direct Matches
// If the rule is defined for the exact same entity being checked, it's a direct match.
if (ruleLevel === currentLevel) {
    if (
        (currentLevel === 'directory' && rule.directoryId === directoryId) ||
        (currentLevel === 'repository' && rule.repositoryId === repositoryId) ||
        (currentLevel === 'global')
    ) {
        // It's a direct match for this specific entity, so the rule applies.
        return true;
    }
}

// 2. For all other cases (potential inheritance), run the full check.
return (
    isPathMatch(rule) &&
    isRepositoryMatch(rule) &&
    isInheritanceMatch(rule)
);
```

