const pendingHref = useRef<string | null>(null);
const go = (href: string) => {
    setOpen(false);
    if (hasUnsavedChanges()) {
        // The guard only reports the block; keep the destination so it can
        // be resumed once the form is clean instead of dropping the jump.
        pendingHref.current = href;
        triggerNavigationBlock();
        return;
    }
    router.push(href);
};
```



