if (userName) {
    const users = await gitlabAPI.Users.all({ search: userName });

    const exactMatchUser = users.find(
        (user) => user.name?.toLowerCase() === userName.toLowerCase(),
    );

    if (exactMatchUser) {
        return exactMatchUser;
    }

    // Candidates exist but no exact match: not a definitive
    // "no such user", so fail the lookup and let the caller
    // apply the short TTL instead of a 30-minute negative entry.
    if (users.length > 0) {
        throw new Error(
            `No exact GitLab user match for "${userName}"`,
        );
    }

    return null;
}
